#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "film_scene_render_binding_candidate.h"
int main(){try{auto graph=loadGraph("work/roundtrip-11.dmx");auto binding=readFilmSceneRenderBindingCandidate(graph,2470);if(binding.models.size()!=1||binding.models.front()!=2552)throw std::runtime_error("empty fixture model coverage");size_t edits=0;for(auto&attribute:graph.elements.at(binding.scene).attributes)if(graph.strings.at(attribute.name)=="children"){if(attribute.type!=15)throw std::runtime_error("scene child array schema");attribute.values.clear();++edits;}if(edits!=1||!readFilmSceneRenderBindingCandidate(graph,2470).models.empty())throw std::runtime_error("empty fixture child edit coverage");saveGraph(graph,"work/empty-scene-session.dmx");graph=loadGraph("work/roundtrip-11.dmx");edits=0;for(auto&attribute:graph.elements.at(2552).attributes)if(graph.strings.at(attribute.name)=="visible"){if(attribute.type!=4||attribute.values.size()!=1||attribute.values[0].wire.size()!=1)throw std::runtime_error("hidden fixture visibility schema");attribute.values[0].wire[0]=0;++edits;}if(edits!=1)throw std::runtime_error("hidden fixture edit coverage");saveGraph(graph,"work/hidden-model-scene-session.dmx");std::cout<<"empty and hidden saved-scene fixtures created\n";return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
